#!/bin/sh
# Write Formula/adf.rb for VERSION from dist/checksums.txt.
# Usage: scripts/render-formula.sh VERSION
set -eu
version="$1"
root="$(cd "$(dirname "$0")/.." && pwd)"
sum() { awk -v f="adf_${version}_$1.tar.gz" '$2 == f {print $1}' "$root/dist/checksums.txt"; }
base="https://github.com/CodeGeek04/agent-desktop-fleet/releases/download/v${version}"
cat > "$root/Formula/adf.rb" <<RUBY
# Generated by scripts/render-formula.sh for each release. Do not edit by hand.
class Adf < Formula
  desc "Fleet of lightweight sandboxed Linux desktops for AI agents"
  homepage "https://github.com/CodeGeek04/agent-desktop-fleet"
  version "${version}"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "${base}/adf_${version}_darwin_arm64.tar.gz"
      sha256 "$(sum darwin_arm64)"
    end
  end

  on_linux do
    on_intel do
      url "${base}/adf_${version}_linux_amd64.tar.gz"
      sha256 "$(sum linux_amd64)"
    end
    on_arm do
      url "${base}/adf_${version}_linux_arm64.tar.gz"
      sha256 "$(sum linux_arm64)"
    end
  end

  def install
    bin.install "adf"
  end

  def caveats
    <<~EOS
      adf runs each desktop in a smolvm microVM. If \`adf doctor\` reports that smolvm is
      missing, install it with:
        curl -sSL https://smolmachines.com/install.sh | bash

      Give your coding agents the adf skill (Claude Code, Codex, Cursor, Gemini CLI,
      GitHub Copilot, OpenCode and more):
        adf skill install

      Or, in Claude Code, install the plugin (skill and MCP tools together):
        /plugin install adf --marketplace CodeGeek04/agent-desktop-fleet
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/adf --version")
  end
end
RUBY
echo "wrote Formula/adf.rb for ${version}"
